// Console outbound payload (deliveries.py):
// { review_item_id, image_base64, submitted_by, secret }
const b = $('Slab Trigger').item.json.body || {};
const submitted = String(b.submitted_by || '').trim();
const local = submitted.split('@')[0] || '';
return { json: {
  review_item_id: String(b.review_item_id || ''),
  image_base64: String(b.image_base64 || ''),
  submitted_by: submitted || null,
  submitted_by_name: local ? (local.charAt(0).toUpperCase() + local.slice(1)) : 'a manager',
  caption: ''
}};

const SUPPLIERS=["Vitoria International","CRS Marble & Granite","MSI","Easy Stones","Cosmos","Triton Stone","Cosentino","Web-Don","Bottega Surfaces","AGM Imports","ACE Granite","StoneBasyx","Encore Stone","Daltile","Architectural Surfaces","Trade Venture Stones","Caesarstone"];
const raw=$input.item.json.content[0].text;
const cleaned=raw.replace(/```json|```/g,'').trim();
let d={}; try{ d=JSON.parse(cleaned); }catch(e){ d={}; }
const num=v=>{ if(v==null)return null; const n=parseFloat(String(v).replace(/[^0-9.]/g,'')); return isNaN(n)?null:n; };
const txt=v=>{ if(v==null)return null; const t=String(v).replace(/\s+/g,' ').trim(); return t.length?t:null; };

let sup=txt(d.supplier_name); let canonical='_Unmatched';
if(sup){ const hit=SUPPLIERS.find(s=>s.toLowerCase()===sup.toLowerCase()); if(hit)canonical=hit; }
const supplierLow=(d.supplier_confidence==='low')||canonical==='_Unmatched';

const slabs=Array.isArray(d.slabs)?d.slabs:[];
const groups={};
for(const s of slabs){
  const key=[txt(s.material)||'',txt(s.finish)||'',txt(s.thickness)||'',txt(s.area)||''].join('||');
  if(!groups[key])groups[key]={material:txt(s.material),finish:txt(s.finish),thickness:txt(s.thickness),area:txt(s.area),unit_price:num(s.unit_price),extended_price:num(s.extended_price),line_sf_total:num(s.line_sf_total),slabs:[]};
  groups[key].slabs.push(s);
}
const materials=Object.values(groups).map(g=>{
  const hasPerSlabSf=g.slabs.some(s=>num(s.square_feet)!=null);
  const perSlabSf=g.slabs.reduce((a,s)=>a+(num(s.square_feet)||0),0);
  const sf=hasPerSlabSf?perSlabSf:(num(g.line_sf_total)||0);
  const serialsArr=g.slabs.map(s=>txt(s.serial_number)).filter(Boolean);
  const barcodesArr=g.slabs.map(s=>txt(s.barcode)).filter(Boolean);
  return {material:g.material,finish:g.finish,thickness:g.thickness,area:g.area,
    slab_count:g.slabs.length,total_sf:Math.round(sf*100)/100,has_per_slab_sf:hasPerSlabSf,
    unit_price:g.unit_price,extended_price:g.extended_price,line_sf_total:g.line_sf_total,
    serials:serialsArr.join(', '),barcodes:barcodesArr.join(', '),
    n_serials:serialsArr.length,n_barcodes:barcodesArr.length,
    lot:(g.slabs.map(s=>txt(s.lot)).filter(Boolean)[0])||null};
});

// Bill of Lading / packing slip: one material, no per-slab serials/barcodes, slip states a package count -> trust it
const pkgCount=parseInt(String(d.package_count==null?'':d.package_count).replace(/[^0-9]/g,''));
if(materials.length===1 && !isNaN(pkgCount) && pkgCount>0 && materials[0].n_serials===0 && materials[0].n_barcodes===0 && pkgCount>materials[0].slab_count){ materials[0].slab_count=pkgCount; }

let qtyOk=true, sfOk=true, priceState='NA', hasPrice=false;
const statedMap={};
if(d.stated_counts){ String(d.stated_counts).split(/[;\n]/).forEach(p=>{ const x=p.split(':'); if(x.length>=2){ const nm=x[0].trim().toLowerCase(); const n=parseInt(x[1].replace(/[^0-9]/g,'')); if(nm&&!isNaN(n))statedMap[nm]=n; } }); }
for(const mt of materials){
  const nm=(mt.material||'').toLowerCase();
  if(statedMap[nm]!=null && statedMap[nm]!==mt.slab_count) qtyOk=false;
  if(mt.line_sf_total!=null && mt.has_per_slab_sf){ if(Math.abs(mt.total_sf-mt.line_sf_total)>Math.max(0.5,mt.line_sf_total*0.02)) sfOk=false; }
  if(mt.unit_price!=null && mt.extended_price!=null && mt.line_sf_total!=null){ hasPrice=true; const expected=mt.line_sf_total*mt.unit_price; if(Math.abs(expected-mt.extended_price)>Math.max(2,mt.extended_price*0.02)) priceState='fail'; }
}
const total=num(d.total), subtotal=num(d.subtotal), tax=num(d.tax);
if(hasPrice && total!=null){ const sumExt=materials.reduce((a,m)=>a+(m.extended_price||0),0); const expected=sumExt+(tax||0); if(Math.abs(expected-total)>Math.max(2,total*0.02)) priceState='fail'; }
if(hasPrice && priceState!=='fail') priceState='pass';

const slabCount=materials.reduce((a,m)=>a+m.slab_count,0);
const validationOk=!((!qtyOk)||(!sfOk)||(priceState==='fail')||supplierLow);

const supName=(canonical||'Unknown').replace(/[\/\\?%*:|"<>]/g,'').trim()||'Unknown';
let ds=txt(d.order_date); let dnorm=null;
if(ds){ const dt=new Date(ds); if(!isNaN(dt)) dnorm=dt.toISOString().slice(0,10); }
if(!dnorm) dnorm=new Date().toISOString().slice(0,10);
const docName=(txt(d.document_number)||'NA').replace(/[\/\\?%*:|"<>\s]/g,'');
const filename=supName+'_'+dnorm+'_'+docName+'.jpg';

// dedup formula: prefer Supplier+Document#, fall back to Supplier+Total+Slab count when no doc#
let dedupFormula;
const docVal=txt(d.document_number);
if(docVal){ const de=docVal.replace(/'/g,"\\'"); dedupFormula="AND({Supplier}='"+canonical+"', {Document #}='"+de+"')"; }
else { dedupFormula="AND({Supplier}='"+canonical+"', {Total}="+(total||0)+", {Slab count}="+slabCount+")"; }

const wb={pushName:$('Trigger Context').item.json.submitted_by_name,key:{id:$('Trigger Context').item.json.review_item_id,participant:''},message:{imageMessage:{caption:null}}};
const manager=(wb.pushName)||(wb.key&&wb.key.participant)||'';
const caption=txt(wb.message&&wb.message.imageMessage&&wb.message.imageMessage.caption);

const issues=[];
if(!qtyOk)issues.push('slab count vs slip');
if(!sfOk)issues.push('square footage');
if(priceState==='fail')issues.push('prices');
if(supplierLow)issues.push('supplier name unclear');
const validation_note=issues.length?('\u26a0\ufe0f Please check: '+issues.join(', ')):'\u2705 Counts / SF / prices check out';
const materials_summary=materials.map(m=>(m.material||'?')+' \u00d7'+m.slab_count).join(', ');

return { json:{
  supplier_canonical:canonical, supplier_confidence:d.supplier_confidence||null, supplier_low:supplierLow,
  document_number:txt(d.document_number), order_date:ds, order_date_iso:dnorm, received:new Date().toISOString(),
  subtotal, tax, total, hand_notes:txt(d.handwritten_notes), caption_job_name:txt(d.caption_job_name),
  caption, manager, message_id:wb.key.id, slab_count:slabCount,
  sf_check:sfOk, qty_check:qtyOk, price_check:priceState, validation_ok:validationOk,
  photo_filename:filename, dedup_formula:dedupFormula, materials, materials_summary, validation_note
}};

const me = $('Trigger Context').item.json.review_item_id;
const hits = ($json.items || []).filter(r => r.review_item_id !== me
  && r.status !== 'duplicate');
return { json: Object.assign({}, $('Parse Slip').item.json,
  { _dupId: hits.length ? hits[0].review_item_id : '' }) };

